def clean_label(label: str) -> str:
    label = label.strip()
    if ' ' in label:
        return ' '.join(label.lower().split())
    else:
        return label.lower()

def clean_label(label: str) -> str:
    label = label.strip()
    return ''.join(char.lower() if char.isspace() else char for char in label)

from decimal import Decimal

def average(a: float, b: float) -> float:
    return Decimal(a + b) / 2

def average(a: float, b: float) -> float:
    return (a + b) / 2.0

def test_average():
    assert average(10, 20) == 15

from decimal import Decimal

def average(a: float, b: float) -> float:
    return (Decimal(a) + Decimal(b)) / 2

from fractions import Fraction

def average(a: float, b: float) -> float:
    return float(Fraction(a).limit_denominator() + Fraction(b).limit_denominator()) / 2

from typing import Union

def average(a: Union[int, float], b: Union[int, float]) -> float:
    return (a + b) / 2.0
